 44→// InstallHooks installs Claude Code hooks in .claude/settings.json.
 45→// If force is true, removes existing Entire hooks before installing.
 46→// Returns the number of hooks installed.
 47→func (c *ClaudeCodeAgent) InstallHooks(ctx context.Context, localDev bool, force bool) (int, error) {
 48→	// Use repo root instead of CWD to find .claude directory
 49→	// This ensures hooks are installed correctly when run from a subdirectory
 50→	repoRoot, err := paths.WorktreeRoot(ctx)
 51→	if err != nil {
 52→		// Fallback to CWD if not in a git repo (e.g., during tests)
 53→		repoRoot, err = os.Getwd() //nolint:forbidigo // Intentional fallback when WorktreeRoot() fails (tests run outside git repos)
 54→		if err != nil {
 55→			return 0, fmt.Errorf("failed to get current directory: %w", err)
 56→		}
 57→	}
 58→
 59→	settingsPath := filepath.Join(repoRoot, ".claude", ClaudeSettingsFileName)
 60→
 61→	// Read existing settings if they exist
 62→	var rawSettings map[string]json.RawMessage
 63→
 64→	// rawHooks preserves unknown hook types (e.g., "Notification", "SubagentStop")
 65→	var rawHooks map[string]json.RawMessage
 66→
 67→	// rawPermissions preserves unknown permission fields (e.g., "ask")
 68→	var rawPermissions map[string]json.RawMessage
 69→
 70→	existingData, readErr := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + settings file name
 71→	if readErr == nil {
 72→		if err := json.Unmarshal(existingData, &rawSettings); err != nil {
 73→			return 0, fmt.Errorf("failed to parse existing settings.json: %w", err)
 74→		}
 75→		if hooksRaw, ok := rawSettings["hooks"]; ok {
 76→			if err := json.Unmarshal(hooksRaw, &rawHooks); err != nil {
 77→				return 0, fmt.Errorf("failed to parse hooks in settings.json: %w", err)
 78→			}
 79→		}
 80→		if permRaw, ok := rawSettings["permissions"]; ok {
 81→			if err := json.Unmarshal(permRaw, &rawPermissions); err != nil {
 82→				return 0, fmt.Errorf("failed to parse permissions in settings.json: %w", err)
 83→			}
 84→		}
 85→	} else {
 86→		rawSettings = make(map[string]json.RawMessage)
 87→	}
 88→
 89→	if rawHooks == nil {
 90→		rawHooks = make(map[string]json.RawMessage)
 91→	}
 92→	if rawPermissions == nil {
 93→		rawPermissions = make(map[string]json.RawMessage)
 94→	}
 95→
 96→	// Parse only the hook types we need to modify
 97→	var sessionStart, sessionEnd, stop, userPromptSubmit, preToolUse, postToolUse []ClaudeHookMatcher
 98→	parseHookType(rawHooks, "SessionStart", &sessionStart)
 99→	parseHookType(rawHooks, "SessionEnd", &sessionEnd)
100→	parseHookType(rawHooks, "Stop", &stop)
101→	parseHookType(rawHooks, "UserPromptSubmit", &userPromptSubmit)
102→	parseHookType(rawHooks, "PreToolUse", &preToolUse)
103→	parseHookType(rawHooks, "PostToolUse", &postToolUse)
104→
105→	// If force is true, remove all existing Entire hooks first
106→	if force {
107→		sessionStart = removeEntireHooks(sessionStart)
108→		sessionEnd = removeEntireHooks(sessionEnd)
109→		stop = removeEntireHooks(stop)
110→		userPromptSubmit = removeEntireHooks(userPromptSubmit)
111→		preToolUse = removeEntireHooksFromMatchers(preToolUse)
112→		postToolUse = removeEntireHooksFromMatchers(postToolUse)
113→	}
114→
115→	// Define hook commands
116→	var sessionStartCmd, sessionEndCmd, stopCmd, userPromptSubmitCmd, preTaskCmd, postTaskCmd, postTodoCmd string
117→	if localDev {
118→		sessionStartCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code session-start"
119→		sessionEndCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code session-end"
120→		stopCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code stop"
121→		userPromptSubmitCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code user-prompt-submit"
122→		preTaskCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code pre-task"
123→		postTaskCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code post-task"
124→		postTodoCmd = "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code post-todo"
125→	} else {
126→		sessionStartCmd = "entire hooks claude-code session-start"
127→		sessionEndCmd = "entire hooks claude-code session-end"
128→		stopCmd = "entire hooks claude-code stop"
129→		userPromptSubmitCmd = "entire hooks claude-code user-prompt-submit"
130→		preTaskCmd = "entire hooks claude-code pre-task"
131→		postTaskCmd = "entire hooks claude-code post-task"
132→		postTodoCmd = "entire hooks claude-code post-todo"
133→	}
134→
135→	count := 0
136→
137→	// Add hooks if they don't exist
138→	if !hookCommandExists(sessionStart, sessionStartCmd) {
139→		sessionStart = addHookToMatcher(sessionStart, "", sessionStartCmd)
140→		count++
141→	}
142→	if !hookCommandExists(sessionEnd, sessionEndCmd) {
143→		sessionEnd = addHookToMatcher(sessionEnd, "", sessionEndCmd)
144→		count++
145→	}
146→	if !hookCommandExists(stop, stopCmd) {
147→		stop = addHookToMatcher(stop, "", stopCmd)
148→		count++
149→	}
150→	if !hookCommandExists(userPromptSubmit, userPromptSubmitCmd) {
151→		userPromptSubmit = addHookToMatcher(userPromptSubmit, "", userPromptSubmitCmd)
152→		count++
153→	}
154→	if !hookCommandExistsWithMatcher(preToolUse, "Task", preTaskCmd) {
155→		preToolUse = addHookToMatcher(preToolUse, "Task", preTaskCmd)
156→		count++
157→	}
158→	if !hookCommandExistsWithMatcher(postToolUse, "Task", postTaskCmd) {
159→		postToolUse = addHookToMatcher(postToolUse, "Task", postTaskCmd)
160→		count++
161→	}
162→	if !hookCommandExistsWithMatcher(postToolUse, "TodoWrite", postTodoCmd) {
163→		postToolUse = addHookToMatcher(postToolUse, "TodoWrite", postTodoCmd)
164→		count++
165→	}
166→
167→	// Add permissions.deny rule if not present
168→	permissionsChanged := false
169→	var denyRules []string
170→	if denyRaw, ok := rawPermissions["deny"]; ok {
171→		if err := json.Unmarshal(denyRaw, &denyRules); err != nil {
172→			return 0, fmt.Errorf("failed to parse permissions.deny in settings.json: %w", err)
173→		}
174→	}
175→	if !slices.Contains(denyRules, metadataDenyRule) {
176→		denyRules = append(denyRules, metadataDenyRule)
177→		denyJSON, err := json.Marshal(denyRules)
178→		if err != nil {
179→			return 0, fmt.Errorf("failed to marshal permissions.deny: %w", err)
180→		}
181→		rawPermissions["deny"] = denyJSON
182→		permissionsChanged = true
183→	}
184→
185→	if count == 0 && !permissionsChanged {
186→		return 0, nil // All hooks and permissions already installed
187→	}
188→
189→	// Marshal modified hook types back to rawHooks
190→	marshalHookType(rawHooks, "SessionStart", sessionStart)
191→	marshalHookType(rawHooks, "SessionEnd", sessionEnd)
192→	marshalHookType(rawHooks, "Stop", stop)
193→	marshalHookType(rawHooks, "UserPromptSubmit", userPromptSubmit)
194→	marshalHookType(rawHooks, "PreToolUse", preToolUse)
195→	marshalHookType(rawHooks, "PostToolUse", postToolUse)
196→
197→	// Marshal hooks and update raw settings
198→	hooksJSON, err := json.Marshal(rawHooks)
199→	if err != nil {
200→		return 0, fmt.Errorf("failed to marshal hooks: %w", err)
201→	}
202→	rawSettings["hooks"] = hooksJSON
203→
204→	// Marshal permissions and update raw settings
205→	permJSON, err := json.Marshal(rawPermissions)
206→	if err != nil {
207→		return 0, fmt.Errorf("failed to marshal permissions: %w", err)
208→	}
209→	rawSettings["permissions"] = permJSON
210→
211→	// Write back to file
212→	if err := os.MkdirAll(filepath.Dir(settingsPath), 0o750); err != nil {
213→		return 0, fmt.Errorf("failed to create .claude directory: %w", err)
214→	}
215→
216→	output, err := jsonutil.MarshalIndentWithNewline(rawSettings, "", "  ")
217→	if err != nil {
218→		return 0, fmt.Errorf("failed to marshal settings: %w", err)
219→	}
220→
221→	if err := os.WriteFile(settingsPath, output, 0o600); err != nil {
222→		return 0, fmt.Errorf("failed to write settings.json: %w", err)
223→	}
224→
225→	return count, nil
226→}
