228→// parseHookType parses a specific hook type from rawHooks into the target slice.
229→// Silently ignores parse errors (leaves target unchanged).
230→func parseHookType(rawHooks map[string]json.RawMessage, hookType string, target *[]ClaudeHookMatcher) {
231→	if data, ok := rawHooks[hookType]; ok {
232→		//nolint:errcheck,gosec // Intentionally ignoring parse errors - leave target as nil/empty
233→		json.Unmarshal(data, target)
234→	}
235→}
236→
237→// marshalHookType marshals a hook type back to rawHooks.
238→// If the slice is empty, removes the key from rawHooks.
239→func marshalHookType(rawHooks map[string]json.RawMessage, hookType string, matchers []ClaudeHookMatcher) {
240→	if len(matchers) == 0 {
241→		delete(rawHooks, hookType)
242→		return
243→	}
244→	data, err := json.Marshal(matchers)
245→	if err != nil {
246→		return // Silently ignore marshal errors (shouldn't happen)
247→	}
248→	rawHooks[hookType] = data
249→}
