```go
// filesTouchedPath returns the path to a session's file tracking file.
func (s *StateStore) filesTouchedPath(sessionID string) string {
	return filepath.Join(s.stateDir, sessionID+".files")
}

// AppendFileTouched appends a file path to the session's tracking file.
// This is an append-only operation — no JSON parsing, no state loading.
// The file is one path per line, deduplication happens on read.
func (s *StateStore) AppendFileTouched(_ context.Context, sessionID, filePath string) error {
	if err := validation.ValidateSessionID(sessionID); err != nil {
		return fmt.Errorf("invalid session ID: %w", err)
	}

	if err := os.MkdirAll(s.stateDir, 0o750); err != nil {
		return fmt.Errorf("failed to create session state directory: %w", err)
	}

	f, err := os.OpenFile(s.filesTouchedPath(sessionID), os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o600) //nolint:gosec // path derived from validated sessionID
	if err != nil {
		return fmt.Errorf("failed to open files tracking: %w", err)
	}
	defer f.Close()

	if _, err := fmt.Fprintln(f, filePath); err != nil {
		return fmt.Errorf("failed to append to files tracking: %w", err)
	}
	return nil
}

// ReadFilesTouched reads the session's file tracking file and returns
// a deduplicated, sorted list of file paths. Returns nil if the file
// doesn't exist or is empty.
func (s *StateStore) ReadFilesTouched(_ context.Context, sessionID string) ([]string, error) {
	if err := validation.ValidateSessionID(sessionID); err != nil {
		return nil, fmt.Errorf("invalid session ID: %w", err)
	}

	data, err := os.ReadFile(s.filesTouchedPath(sessionID)) //nolint:gosec // path derived from validated sessionID
	if os.IsNotExist(err) {
		return nil, nil //nolint:nilnil // no tracking file = no files tracked
	}
	if err != nil {
		return nil, fmt.Errorf("failed to read files tracking: %w", err)
	}

	// Deduplicate
	seen := make(map[string]struct{})
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if line != "" {
			seen[line] = struct{}{}
		}
	}

	if len(seen) == 0 {
		return nil, nil //nolint:nilnil // empty file = no files tracked
	}

	result := make([]string, 0, len(seen))
	for f := range seen {
		result = append(result, f)
	}
	sort.Strings(result)
	return result, nil
}

// ClearFilesTouched removes the session's file tracking file.
func (s *StateStore) ClearFilesTouched(_ context.Context, sessionID string) error {
	if err := validation.ValidateSessionID(sessionID); err != nil {
		return fmt.Errorf("invalid session ID: %w", err)
	}

	if err := os.Remove(s.filesTouchedPath(sessionID)); err != nil && !os.IsNotExist(err) {
		return fmt.Errorf("failed to remove files tracking: %w", err)
	}
	return nil
}
```

